// ===================== LOADING SCREEN =====================
function LoadingScreen({ onFinish }) {
  const [phase, setPhase] = useState(0);
  const letters = ["ر", "ا", "و", "ی"];

  useEffect(() => {
    const timers = [];
    letters.forEach((_, i) => {
      timers.push(setTimeout(() => setPhase(i + 1), i * 300 + 200));
    });
    timers.push(setTimeout(() => onFinish(), 2200));
    return () => timers.forEach(clearTimeout);
  }, []);

  return (
    <div style={{
      position: "fixed", inset: 0, background: "#fff",
      display: "flex", flexDirection: "column",
      alignItems: "center", justifyContent: "center",
      zIndex: 9999, direction: "rtl"
    }}>
      <div style={{ display: "flex", gap: "8px", alignItems: "center" }}>
        {letters.map((letter, i) => (
          <span key={i} style={{
            fontSize: "72px", fontWeight: "900",
            color: "#E8521A",
            opacity: phase > i ? 1 : 0,
            transform: phase > i ? "translateY(0) scale(1)" : "translateY(20px) scale(0.8)",
            transition: "all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)",
            display: "inline-block",
            fontFamily: "Vazir, Tahoma, sans-serif",
          }}>{letter}</span>
        ))}
      </div>
      <div style={{
        marginTop: "24px",
        width: "60px", height: "4px",
        background: "#f0f0f0",
        borderRadius: "2px",
        overflow: "hidden",
        opacity: phase >= 4 ? 1 : 0,
        transition: "opacity 0.3s",
      }}>
        <div style={{
          height: "100%",
          background: "#E8521A",
          borderRadius: "2px",
          animation: "loadingBar 1.5s ease-in-out",
        }} />
      </div>
      <style>{`
        @keyframes loadingBar {
          from { width: 0; }
          to { width: 100%; }
        }
      `}</style>
    </div>
  );
}

// ===================== ORANGE CIRCLES BACKGROUND =====================
function OrangeCircles() {
  const circles = Array.from({ length: 15 }, (_, i) => ({
    id: i,
    size: 40 + Math.random() * 60,
    x: Math.random() * 100,
    y: Math.random() * 100,
    duration: 8 + Math.random() * 12,
    delay: Math.random() * -15,
    opacity: 0.55 + Math.random() * 0.35,
  }));

  return (
    <div style={{
      position: "absolute", inset: 0, overflow: "hidden", zIndex: 0,
    }}>
      {circles.map((c) => (
        <div key={c.id} style={{
          position: "absolute",
          width: c.size + "px",
          height: c.size + "px",
          borderRadius: "50%",
          background: `radial-gradient(circle at 35% 35%, #FF8C00, #E8521A)`,
          left: c.x + "%",
          top: c.y + "%",
          opacity: c.opacity,
          animation: `floatCircle${c.id % 3} ${c.duration}s ${c.delay}s ease-in-out infinite`,
          boxShadow: "0 4px 20px rgba(232,82,26,0.4)",
        }} />
      ))}
      <style>{`
        @keyframes floatCircle0 {
          0%, 100% { transform: translate(0, 0) scale(1); }
          33% { transform: translate(30px, -40px) scale(1.1); }
          66% { transform: translate(-20px, 20px) scale(0.9); }
        }
        @keyframes floatCircle1 {
          0%, 100% { transform: translate(0, 0) scale(1); }
          33% { transform: translate(-35px, 25px) scale(0.85); }
          66% { transform: translate(25px, -35px) scale(1.15); }
        }
        @keyframes floatCircle2 {
          0%, 100% { transform: translate(0, 0) scale(1); }
          50% { transform: translate(20px, 30px) scale(1.05); }
        }
      `}</style>
    </div>
  );
}

// ===================== LOGIN PAGE =====================
function LoginPage({ onLogin }) {
  const [phone, setPhone] = useState("");
  const [otp, setOtp] = useState("");
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleSendOtp = async () => {
    if (!phone || phone.length < 10) {
      setError("شماره موبایل معتبر وارد کنید");
      return;
    }
    setLoading(true);
    setError("");
    await new Promise(r => setTimeout(r, 1000));
    setLoading(false);
    setStep(2);
  };

  const handleVerify = async () => {
    if (!otp || otp.length < 4) {
      setError("کد تأیید را وارد کنید");
      return;
    }
    setLoading(true);
    setError("");
    await new Promise(r => setTimeout(r, 1000));
    setLoading(false);
    onLogin();
  };

  return (
    <div style={{
      minHeight: "100vh", background: "#fff",
      display: "flex", alignItems: "center",
      justifyContent: "center",
      position: "relative",
      overflow: "hidden",
      fontFamily: "Vazir, Tahoma, sans-serif",
    }}>
      <OrangeCircles />
      {/* Blur overlay */}
      <div style={{
        position: "absolute", inset: 0,
        backdropFilter: "blur(8px)",
        background: "rgba(255,255,255,0.3)",
        zIndex: 1,
      }} />
      {/* Login Card */}
      <div style={{
        position: "relative", zIndex: 2,
        background: "#fff",
        borderRadius: "24px",
        padding: "40px 32px",
        width: "360px",
        maxWidth: "90vw",
        boxShadow: "0 20px 60px rgba(0,0,0,0.15), 0 4px 20px rgba(232,82,26,0.1)",
        direction: "rtl",
      }}>
        {/* Logo */}
        <div style={{ textAlign: "center", marginBottom: "28px" }}>
          <img src={IMAGES.logo} alt="راوی" style={{
            height: "70px", objectFit: "contain",
          }} />
        </div>
        <h2 style={{
          textAlign: "center", color: "#1a1a2e",
          fontSize: "20px", fontWeight: "700",
          margin: "0 0 8px",
        }}>
          {step === 1 ? "ورود به راوی" : "تأیید شماره موبایل"}
        </h2>
        <p style={{
          textAlign: "center", color: "#888",
          fontSize: "13px", margin: "0 0 28px",
        }}>
          {step === 1 ? "شماره موبایل خود را وارد کنید" : `کد ارسال شده به ${phone} را وارد کنید`}
        </p>

        {step === 1 ? (
          <>
            <input
              type="tel"
              placeholder="09xxxxxxxxx"
              value={phone}
              onChange={e => setPhone(e.target.value)}
              style={{
                width: "100%", padding: "14px 16px",
                border: "2px solid #eee",
                borderRadius: "12px",
                fontSize: "16px", direction: "ltr",
                textAlign: "center",
                outline: "none",
                boxSizing: "border-box",
                fontFamily: "inherit",
                transition: "border-color 0.2s",
              }}
              onFocus={e => e.target.style.borderColor = "#E8521A"}
              onBlur={e => e.target.style.borderColor = "#eee"}
            />
            {error && <p style={{ color: "#e53e3e", fontSize: "12px", marginTop: "8px", textAlign: "center" }}>{error}</p>}
            <button onClick={handleSendOtp} disabled={loading} style={{
              width: "100%", marginTop: "16px",
              padding: "14px",
              background: loading ? "#ccc" : "linear-gradient(135deg, #FF8C00, #E8521A)",
              color: "#fff", border: "none",
              borderRadius: "12px", fontSize: "16px",
              fontWeight: "700", cursor: loading ? "not-allowed" : "pointer",
              fontFamily: "inherit",
              transition: "transform 0.1s",
            }}>
              {loading ? "در حال ارسال..." : "دریافت کد تأیید"}
            </button>
          </>
        ) : (
          <>
            <input
              type="text"
              placeholder="کد ۴ رقمی"
              value={otp}
              onChange={e => setOtp(e.target.value)}
              maxLength={6}
              style={{
                width: "100%", padding: "14px 16px",
                border: "2px solid #eee",
                borderRadius: "12px",
                fontSize: "24px", direction: "ltr",
                textAlign: "center",
                outline: "none",
                boxSizing: "border-box",
                fontFamily: "inherit",
                letterSpacing: "8px",
                transition: "border-color 0.2s",
              }}
              onFocus={e => e.target.style.borderColor = "#E8521A"}
              onBlur={e => e.target.style.borderColor = "#eee"}
            />
            {error && <p style={{ color: "#e53e3e", fontSize: "12px", marginTop: "8px", textAlign: "center" }}>{error}</p>}
            <button onClick={handleVerify} disabled={loading} style={{
              width: "100%", marginTop: "16px",
              padding: "14px",
              background: loading ? "#ccc" : "linear-gradient(135deg, #FF8C00, #E8521A)",
              color: "#fff", border: "none",
              borderRadius: "12px", fontSize: "16px",
              fontWeight: "700", cursor: loading ? "not-allowed" : "pointer",
              fontFamily: "inherit",
            }}>
              {loading ? "در حال بررسی..." : "ورود"}
            </button>
            <button onClick={() => setStep(1)} style={{
              width: "100%", marginTop: "8px",
              padding: "10px", background: "none",
              border: "none", color: "#E8521A",
              fontSize: "14px", cursor: "pointer",
              fontFamily: "inherit",
            }}>
              ویرایش شماره موبایل
            </button>
          </>
        )}
      </div>
    </div>
  );
}

// ===================== COUNTDOWN TIMER =====================
function CountdownTimer({ targetDate }) {
  const [time, setTime] = useState({ d: 0, h: 0, m: 0, s: 0 });

  useEffect(() => {
    const calc = () => {
      const diff = new Date(targetDate) - new Date();
      if (diff <= 0) return { d: 0, h: 0, m: 0, s: 0 };
      const s = Math.floor(diff / 1000);
      return {
        d: Math.floor(s / 86400),
        h: Math.floor((s % 86400) / 3600),
        m: Math.floor((s % 3600) / 60),
        s: s % 60,
      };
    };
    setTime(calc());
    const iv = setInterval(() => setTime(calc()), 1000);
    return () => clearInterval(iv);
  }, [targetDate]);

  const pad = n => String(n).padStart(2, "0");

  return (
    <div style={{ display: "flex", gap: "8px", direction: "rtl" }}>
      {[["روز", time.d], ["ساعت", time.h], ["دقیقه", time.m], ["ثانیه", time.s]].map(([label, val]) => (
        <div key={label} style={{
          textAlign: "center",
          background: "rgba(232,82,26,0.15)",
          borderRadius: "10px",
          padding: "8px 10px",
          minWidth: "50px",
          border: "1px solid rgba(232,82,26,0.3)",
        }}>
          <div style={{
            fontSize: "20px", fontWeight: "800",
            color: "#E8521A", lineHeight: 1,
          }}>{pad(val)}</div>
          <div style={{ fontSize: "10px", color: "#94a3b8", marginTop: "4px" }}>{label}</div>
        </div>
      ))}
    </div>
  );
}

